-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Creates a request after validating the live route, character and destination.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local CancelTimer = Shared.CancelTimer
local CaptureContext = Shared.CaptureContext
local ContextCurrent = Shared.ContextCurrent
local Distance = Shared.Distance
local Enabled = Shared.Enabled
local Exempt = Shared.Exempt
local L = Shared.L
local NavigationText = Shared.NavigationText
local ObjectiveStep = Shared.ObjectiveStep
local PlanningRequestCurrent = Shared.PlanningRequestCurrent
local Position = Shared.Position
local ReadableLocationValue = Shared.ReadableLocationValue
local SameAccess = Shared.SameAccess
local SameLocationFields = Shared.SameLocationFields
local SameWaypointConnection = Shared.SameWaypointConnection
local TerrainRequired = Shared.TerrainRequired
local WalkingProvider = Shared.WalkingProvider

function nav:Update(context)
    local updateStartedAt = debugprofilestop and debugprofilestop()
    if APR.routeValidationPending or APR.routeValidationFailed then return end
    local profile = APR.settings and APR.settings.profile
    if self.worldLoading then
        if profile and profile.enableAddon == false then self:Cancel("disabled") end
        return
    end
    if not Enabled() then
        self:Cancel("disabled")
        return
    end
    if
        not (APR.Services and APR.Services:GetStep())
        and APR.RefreshNavigationUnlockRoute
        and APR:RefreshNavigationUnlockRoute()
    then
        return
    end
    if APR.stepUpdatePending or APR.stepUpdateTimer or APR.stepUpdateRunning then
        self:RequestUpdate()
        return
    end
    if UnitIsDeadOrGhost and UnitIsDeadOrGhost("player") then
        self:Cancel("dead")
        return
    end
    context = type(context) == "table" and (context.route or context.service) and context or CaptureContext()
    if not ContextCurrent(context) then return end
    if self:IsNavigating() and self:GetActiveStep().kind == "taxi" and UnitOnTaxi and UnitOnTaxi("player") then
        return
    end
    local start = Position()
    local resumed, continuation = self:TryResumeAfterTransition(start)
    if resumed or continuation == "waiting" then
        self:Render()
        return
    end
    local transportArrived = self.reason == "transport_arrived"
    local landing = self.transportLanding
    if landing and start then
        self.transportLanding = nil
        local data = APR.NavigationData
        if
            start.z == nil
            and Distance(start, landing) <= Constants.LANDING_HEIGHT_REUSE_YARDS
            and data
            and data.IsSameAccessRegion
            and data:IsSameAccessRegion(start, landing) == true
        then
            start.z = landing.z
        end
    end
    if not self.dirty and ContextCurrent(self._routedStepContext) and not self:HasPlanningInputsChanged(start) then
        return
    end
    local step = ObjectiveStep()
    if not step then
        self:Cancel("no_step")
        return
    end
    if
        step._navigationUnlock
        and step.unlockAction
        and step.unlockAction.positionOptional
        and not step.unlockAction.target
    then
        self._routeInputs = nil
        self:MarkRouteReady()
        return
    end
    if Exempt(step) then
        self._routeInputs = nil
        self:MarkRouteReady()
        return
    end
    if not APR.NavigationData or APR.NavigationData.profile == "unsupported" then
        self:Cancel("unsupported")
        self.state, self.reason, self.context = "waiting_data", "unsupported", context
        self:Notify()
        return
    end
    local goal, map, entranceReason, entranceBlockers, coordinateFree
    if not step._service and (step.Coord or step.Coords) and APR.Services and APR.Services.training then
        APR.Services:CancelTraining()
    end
    goal, map, entranceReason, entranceBlockers, coordinateFree = self:GetDestination(step)
    if entranceReason then
        self:Cancel("entrance")
        self.state = entranceReason == "pending_data" and "waiting_data" or "no_path"
        self.reason, self.context, APR.IsInRouteZone = entranceReason, context, false
        self.blockers = entranceBlockers
        self:Notify()
        if self.state == "no_path" and not step._service and APR.StartNavigationUnlock then
            APR:StartNavigationUnlock(entranceBlockers, context)
        end
        return
    end
    if not goal and self:RequiresScenarioNavigation(step) then
        local scenario = APR:GetScenarioZoneInfo(APR:GetScenarioMapIDForStep(step))
        if scenario and scenario.Coord then
            local c = scenario.Coord
            goal = {
                x = c.y,
                y = c.x,
                uiMapID = c.mapID or map,
                instanceID = c.instanceID or (map and C_Map.GetWorldPosFromMapPos(map, CreateVector2D(0.5, 0.5))),
            }
        end
    end
    if not goal and coordinateFree and not self:RequiresScenarioNavigation(step) then
        -- Native map identity is sufficient for a positionless instruction.
        -- Moving transports can lack world/map coordinates or a continent.
        local currentMap = APR.GetPlayerMapID and APR:GetPlayerMapID()
            or (C_Map and C_Map.GetBestMapForUnit and C_Map.GetBestMapForUnit("player"))
        if
            type(currentMap) == "number"
            and ReadableLocationValue(currentMap)
            and map
            and (currentMap == map or APR:GetPlayerParentMapID() == map)
        then
            self._routeInputs = nil
            self:MarkRouteReady()
            return
        end
    end
    if self:GuideRestrictedInstance(context, step, start, goal, map) then return end
    if not start or (not start.uiMapID and not start.region) or not goal then
        -- Preserve a confirmed transport during loading, but invalidate any
        -- unconfirmed search so it cannot publish after its position vanished.
        if self:IsNavigating() and ContextCurrent(self.context) then
            self.generation = self.generation + 1
            self:CancelLocalPath()
            CancelTimer(self._searchTimer)
            self._searchTimer = nil
            if self.search then self.search:Cancel() end
            self.search, self.recomputeKeepingPath = nil, nil
            return
        end
        self:Cancel("position")
        self.state, self.reason, self.context, APR.IsInRouteZone = "waiting_data", "position", context, false
        self:Notify()
        return
    end
    local serviceItinerary, serviceDeparture = step.serviceItinerary, step.serviceDeparture
    step.serviceItinerary, step.serviceDeparture = nil, nil
    if
        serviceItinerary
        and (
            step.serviceGeometry ~= APR.navigationGeometryRevision
            or not SameLocationFields(start, serviceDeparture, Constants.LOCATION_FIELDS)
        )
    then
        serviceItinerary = nil
    end
    local walkingProvider = WalkingProvider()
    start = self:ObserveWalkingPosition(start, walkingProvider)
    if step._service and start.z == nil then
        local provider, origin = walkingProvider, step.serviceOrigin
        if provider and origin and SameAccess(start, origin) and start.x == origin.x and start.y == origin.y then
            start.z = origin.z
        elseif provider and provider.GetServiceOriginHeight and self.state == "guiding" then
            start.z = provider:GetServiceOriginHeight(start, self:GetActiveStep())
        end
    end
    if step._service then step.serviceOrigin = nil end
    if self:GuideHousingExit(context, step, start, goal) then return end
    local threshold = self:GetThreshold()
    local training = not step.Coord
        and not step.Coords
        and (step.LearnProfession or step.LearnSkill)
        and APR.Services
        and APR.Services.training
    self.zoneReady = training and APR.NavigationData:IsServiceArrival(start, goal)
        or (
            not training
            and not step._service
            and APR:CheckNavigationZoneReady(goal, { step = step, playerPosition = start, threshold = threshold })
        )
    -- A nearby objective is still a candidate for portals, toys and spells.
    -- The search compares complete travel times; zone readiness only controls
    -- whether the authored objective can remain visible while that work runs.
    local sameGeometry = not self._routeInputs or self._routeInputs.geometryRevision == APR.navigationGeometryRevision
    local sameObjective = not self._routeInputs or self:IsObjectiveCurrent(self._routeInputs)
    local hadGuidance = self._routeInputs
        and sameObjective
        and ContextCurrent(self._routedStepContext)
        and (self._routeInputs.hadGuidance or self:IsNavigating())
    local keepPath = sameGeometry and sameObjective and self:IsItineraryValid()
    local keepDirect = self.zoneReady
        and self:IsDirectRouteValid(start)
        and self.destination.instanceID == goal.instanceID
        and self.destination.uiMapID == goal.uiMapID
        and self.destination.x == goal.x
        and self.destination.y == goal.y
    -- On the first plan there is no previous publication to retain. The same
    -- provider can already prove direct access without preparing its catalogue.
    -- Keep zone readiness (including its distance/access rules) authoritative;
    -- unlock instructions still need their normal action/entrance planning.
    local data = APR.NavigationData
    local waypointLeg = step.waypointLeg
    step.waypointLeg = nil
    local waypointResume, savedLanding = self:GetWaypointResume(step.waypointResume, start, goal)
    step.waypointResume = nil
    if savedLanding and Distance(start, savedLanding) <= Constants.WAYPOINT_LANDING_REUSE_YARDS then
        if start.z == nil and Distance(start, savedLanding) <= Constants.LANDING_HEIGHT_REUSE_YARDS then
            start.z = savedLanding.z
        end
        waypointLeg = { from = start, to = goal, destination = true }
    end
    if step._mapWaypoint and sameObjective and not waypointLeg then
        if
            self.search
            and self.search.request
            and self.search.request.waypointResume
            and not self:HasPlanningInputsChanged(start)
        then
            self.dirty = false
            return
        end
        if
            self.search
            and self.waypointPendingLeg
            and self.waypointPendingLeg.before
            and (self:IsItineraryValid() or not self:GetActiveStep())
        then
            self.dirty = false
            return
        end
        -- An access event can offer a new transport or remove an old one.
        -- Movement, loading and geometry changes only affect the active leg.
        if
            not self.dirty
            or not Constants.serviceAccessChanges[self.lastInvalidation]
            or self.lastInvalidation == "world_transition"
        then
            local retained, repair = self:RefreshWaypointLeg(
                start,
                walkingProvider,
                sameGeometry or self.lastInvalidation == "world_transition"
            )
            if retained then
                self._routeInputs = self:CapturePlanningInputs(step, start, context)
                self.start, self.dirty, self._resumeAfterTransition, self._transitionProbe = start, false, nil, nil
                self:Notify()
                return
            end
            waypointLeg = repair
        end
    end
    if waypointLeg then
        keepPath, keepDirect = false, false
    end
    local sameWalkingArea = data.profile == "forever" and walkingProvider and data:CanWalk(start, goal) == true
    local preferLocal = sameWalkingArea
        and (not step._service or step.serviceWaypoint)
        and not training
        and not step._navigationUnlock
    local wasLocalWalk = self._localWalk
    if keepPath and wasLocalWalk and preferLocal and not self:HasPlanningInputsChanged(start) then
        self.dirty = false
        return
    end
    -- Missing geography can become available after the first slice. Retry only
    -- an unpublished cold baseline for the same objective/context/geometry.
    local coldDirect = not self._routeInputs
        or (self._directBaselinePending and sameGeometry and sameObjective and ContextCurrent(self._routedStepContext))
    local seedDirect = coldDirect
        and not TerrainRequired(start, goal, walkingProvider)
        and not step._navigationUnlock
        and self.zoneReady == true
        and data.CanWalk
        and data:CanWalk(start, goal) == true
    if not ContextCurrent(context) then return end
    local retainedArrow = not keepPath and not keepDirect and self:CaptureRetainedArrow(start)
    if keepPath or keepDirect then
        self.generation = self.generation + 1
        self:CancelLocalPath()
        CancelTimer(self._searchTimer)
        self._searchTimer = nil
        if self.search then self.search:Cancel() end
    else
        self:Cancel("replan", retainedArrow ~= nil)
        self.retainedArrow = retainedArrow
    end
    self.context, self._routedStepContext, self.destination, self.start = context, context, goal, start
    self.waypointDestinationContext = nil
    self.dirty, self.state, APR.IsInRouteZone =
        false, keepPath and "guiding" or ((keepDirect or seedDirect) and "ready" or "planning"), self.zoneReady == true
    self._resumeAfterTransition = nil
    self._transitionProbe = nil
    self.recomputeKeepingPath = keepPath
    self._localWalk = nil
    self.recomputeKeepingDirect = keepDirect or seedDirect
    self._routeInputs = self:CapturePlanningInputs(step, start, context)
    self._routeInputs.hadGuidance = hadGuidance or nil
    self._directBaselinePending = coldDirect and not seedDirect or nil
    if data.profile == "forever" and IsIndoors then
        start.indoors = self._routeInputs.indoors
    end
    self.showOutOfZoneStepContent = self.zoneReady == true
    local walkSpeed, walkingSpeedCeiling, walkSpeedAt, walkSpeedFor = self:GetWalkingSpeedModel(start, threshold)
    self.plannedWalkSpeed = walkSpeed
    local generation = self.generation
    local areaObjective = step.Qpart ~= nil and goal.accessKey == nil
    local goalRange = walkingProvider
            and (step.Waypoint or areaObjective)
            and not step._service
            and goal.z == nil
            and goal.floor == nil
            and type(step.Range) == "number"
            and step.Range > 0
            and step.Range
        or nil
    self._routeInputs.walkingGoalRange = goalRange
    local goalXY = walkingProvider
        and goal.z == nil
        and goal.floor == nil
        and (
            step._mapWaypoint == true
            or (not step._service and not step._navigationUnlock and (step.Coord ~= nil or step.Coords ~= nil))
        )
    local withinWalkingThreshold = Distance(start, goal) < threshold
    local distantMapWaypoint = step._mapWaypoint and not withinWalkingThreshold and start.uiMapID ~= goal.uiMapID
    local separatedTravel = data.profile == "forever"
        and not sameWalkingArea
        and (not step._service or step._mapWaypoint)
        and not step._navigationUnlock
    local corridor = data.profile == "forever"
            and self.lastWalkGeometry == APR.navigationGeometryRevision
            and self.lastWalkCorridor
        or nil
    local contextKey = tostring(context.route) .. ":" .. tostring(context.index) .. ":" .. tostring(context.revision)
    if step._mapWaypoint then contextKey = contextKey .. ":waypoint:" .. tostring(context.service) end
    self.waitingData = false
    if waypointLeg then
        self.waypointJourney, self.waypointPendingLeg = true, waypointLeg
        if waypointLeg.before then
            self.queue, self.cursor, self.state = waypointLeg.before, 1, "guiding"
        end
    end
    self.search = APR.NavigationPlanner:Create({
        -- Ordinary travel compares elapsed time across every available action.
        -- Access-only routing intentionally prefers a physical entrance and
        -- must be reserved for the steps that explain or unlock that entrance.
        allowTaxiProbes = not training
            and (
                step._service ~= true
                or data.profile == "forever" and step._mapWaypoint and (distantMapWaypoint or separatedTravel)
            ),
        serviceTravel = (step._service == true and not step._mapWaypoint) or training ~= nil and training ~= false,
        preferZoneAccess = step._navigationUnlock == true,
        localObjective = step._navigationUnlock == true,
        adapter = APR.NavigationAdapter,
        data = data,
        walkingProvider = walkingProvider,
        walkingOrigin = start,
        walkingOriginCorridor = corridor,
        walkingGoal = goal,
        walkingGoalRange = goalRange,
        walkingGoalPreferRange = areaObjective,
        walkingGoalXY = goalXY,
        walkingGoalApproach = goalXY
                and step._mapWaypoint
                and data.profile == "forever"
                and (distantMapWaypoint or separatedTravel)
                and Constants.MAP_WAYPOINT_APPROACH_RADIUS
            or nil,
        allowEarlyWalkingApproach = distantMapWaypoint
            and start.instanceID == goal.instanceID
            and start.region == goal.region,
        previewWalking = data.profile == "forever",
        previewEntryWalk = separatedTravel
            or data.profile == "forever" and step.serviceWaypoint == true and not sameWalkingArea,
        previewAccess = separatedTravel and not keepPath and not keepDirect and walkingProvider ~= nil,
        waypointLeg = waypointLeg,
        waypointResume = waypointResume,
        sameWaypointConnection = SameWaypointConnection,
        planWaypointLanding = step._mapWaypoint == true and start.instanceID ~= goal.instanceID,
        progressiveTravel = data.profile == "forever"
            and (start.instanceID ~= goal.instanceID or distantMapWaypoint)
            and (not step._service or step._mapWaypoint)
            and not step._navigationUnlock,
        protectWalkingCoverage = data.profile == "forever",
        batchTerrainWork = preferLocal or separatedTravel or (data.profile == "forever" and step._service == true),
        walkingSpeedCeiling = walkingProvider and walkingSpeedCeiling or nil,
        taxiData = APR.taxiData,
        allowTaxiDiscovery = data.profile == "forever",
        allowTaxiStops = data.profile == "forever" and not training and not step._navigationUnlock
            and (not step._service or step._mapWaypoint) and not step.GetFP and not step.UseFlightPath,
        deferInstructions = true,
        engine = APR.NavigationEngine,
        start = start,
        playerPosition = start,
        goal = goal,
        hearthstoneGoal = goal,
        clock = debugprofilestop,
        walkSpeed = walkSpeed,
        walkSpeedFor = walkSpeedFor,
        walkSpeedAt = walkSpeedAt,
        contextKey = contextKey,
        walkingIsTransitive = true,
        budget = GetMoney and GetMoney() or 0,

        canWalk = --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/controller/NavigationSearch.lua:419:callback#2", --[[/APR_DIAG]]function(from, to) return data:CanWalk(from, to) end--[[APR_DIAG]])--[[/APR_DIAG]],
        walkingRegionFor = data.GetPositionRegion and --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/controller/NavigationSearch.lua:420:callback#3", --[[/APR_DIAG]]function(point) return data:GetPositionRegion(point) end--[[APR_DIAG]])--[[/APR_DIAG]],

        prepareSegment = --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/controller/NavigationSearch.lua:422:callback#4", --[[/APR_DIAG]]function(segment, index)
            return self:PrepareGuidanceStep(segment, index, generation, start)
        end--[[APR_DIAG]])--[[/APR_DIAG]],

        probeSegments = --[[APR_DIAG]]APRTrace("APR-Core/features/navigation/controller/NavigationSearch.lua:426:callback#5", --[[/APR_DIAG]]function(probe)
            return {
                { kind = "walk", from = start, to = probe.from, instruction = NavigationText("RUN_WAYPOINT") },
                {
                    kind = "verify_taxi",
                    from = probe.from,
                    to = probe.from,
                    fromNodeID = probe.fromNodeID,
                    toNodeID = probe.toNodeID,
                    seconds = probe.flightSeconds,
                    copper = probe.discoveryFare,
                    probeDestination = probe.flightDestination,
                    instruction = probe.discoveryFare ~= nil and APR.GetFlightPathDiscoveryText
                        and APR:GetFlightPathDiscoveryText({ GetFP = probe.fromNodeID })
                        or L["NAVIGATION_CONSULT_TAXI"],
                    contextKey = contextKey,
                },
            }
        end--[[APR_DIAG]])--[[/APR_DIAG]],
    })
    local worldJob, inputs = self.search, self._routeInputs
    local reuseItinerary = serviceItinerary
        and worldJob.BeginQueue
        and self:CanReuseServiceItinerary(serviceItinerary, start, goal, walkingProvider)
    if not PlanningRequestCurrent(self, context, generation, worldJob, inputs) then return end
    if reuseItinerary then
        worldJob.serviceDeparture = serviceDeparture
        worldJob.result = serviceItinerary
        worldJob:BeginQueue()
    elseif
        not waypointLeg
        and not waypointResume
        and (not keepPath or wasLocalWalk)
        and not step._navigationUnlock
        and walkingProvider
        and walkingProvider.CreatePathJob
        and (withinWalkingThreshold or step._mapWaypoint and (not distantMapWaypoint or transportArrived and sameWalkingArea))
        and TerrainRequired(start, goal, walkingProvider)
        and data:CanWalk(start, goal) == true
    then
        local localJob = walkingProvider:CreatePathJob(start, goal, {
            walkSpeed = walkSpeed,
            walkSpeedFor = walkSpeedFor,
            walkSpeedAt = walkSpeedAt,
            clock = debugprofilestop,
            serviceWalking = (step._service and not step._mapWaypoint) or training ~= nil and training ~= false,
            quick = not distantMapWaypoint and (preferLocal or step._mapWaypoint) or nil,
            walkingPartialGoal = step._mapWaypoint == true,
            walkingGoalApproach = distantMapWaypoint and Constants.MAP_WAYPOINT_APPROACH_RADIUS or nil,
            previewDeparture = step._mapWaypoint == true and data.profile == "forever",
            walkingOrigin = start,
            walkingOriginCorridor = corridor,
            walkingGoal = goal,
            walkingGoalRange = goalRange,
            walkingGoalPreferRange = areaObjective,
            walkingGoalXY = goalXY,
            previewWalking = data.profile == "forever",
        })
        if not PlanningRequestCurrent(self, context, generation, worldJob, inputs) then
            if localJob and localJob.Cancel then localJob:Cancel() end
            return
        end
        self.localPathJob = localJob
    end

    self:RunPlanningSearch({
        context = context,
        generation = generation,
        data = data,
        start = start,
        goal = goal,
        step = step,
        walkingProvider = walkingProvider,
        keepPath = keepPath,
        keepDirect = keepDirect,
        reuseItinerary = reuseItinerary,
        preferLocal = preferLocal,
        walkSpeed = walkSpeed,
        walkSpeedFor = walkSpeedFor,
        updateStartedAt = updateStartedAt,
        seedDirect = seedDirect,
        waypointLeg = waypointLeg,
    })
end--[[APR_DIAG]]; nav.Update = APRTrace("APR-Core/features/navigation/controller/NavigationSearch.lua:30:nav:Update#1", nav.Update)--[[/APR_DIAG]]
